<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$action=(string)($_POST['action']??'');if($action==='accept_legal')$requiredActions->acceptLegal((int)$_POST['action_id'],(int)$user['id']);elseif($action==='change_password')$requiredActions->completePasswordChange((int)$_POST['action_id'],(int)$user['id'],(string)$_POST['password']);$message='<div class="alert success">Wymagana akcja została wykonana.</div>';}catch(Throwable $e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$requiredActions->refreshAutomaticCompletions((int)$user['id']);$items=$requiredActions->pending((int)$user['id']);if($items===[]){$return=(string)($_SESSION['required_action_return']??'/dashboard');unset($_SESSION['required_action_return']);Web::redirect($return);} $html='';foreach($items as $a){$type=(string)$a['action_type'];$control='';if(in_array($type,['accept_terms','accept_privacy'],true)){$payload=json_decode((string)$a['payload_json'],true);$doc=$db->one('SELECT * FROM legal_documents WHERE id=?',[(int)($payload['legal_document_id']??0)]);$control='<div class="legal-doc">'.nl2br(Web::e($doc['content']??'')).'</div><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="action_id" value="'.(int)$a['id'].'"><button class="primary" name="action" value="accept_legal">Akceptuję</button></form>';}elseif($type==='change_password'){$control='<form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="action_id" value="'.(int)$a['id'].'"><label>Nowe hasło<input type="password" name="password" minlength="12" required></label><button name="action" value="change_password">Zmień hasło</button></form>';}elseif($type==='setup_mfa')$control='<a class="button" href="/account/passkeys">Skonfiguruj Passkey / MFA</a>';elseif($type==='verify_email')$control='<a class="button" href="/account/emails">Zweryfikuj e-mail</a>';else$control='<div class="alert warning">Ta akcja wymaga działania administratora.</div>';$html.='<section class="card"><h2>'.Web::e($type).'</h2>'.$control.'</section>';}
Web::page('Wymagane akcje','<div class="page-head"><div><h1>Wymagane akcje</h1><p>Musisz wykonać je przed kontynuowaniem logowania do aplikacji.</p></div></div>'.$message.$html,$user);
